    private static Set<String> findRulesSharingFiles(Map<String, RuleFile> ruleFiles) {
        // only rule files with the same file name or the same file key can possibly be shared, so we just compare those.
        // If the file system does not support file keys (e.g. on Windows) all regular files have to be compared to each other.
        Map<String, List<String>> rulesByFileName = new HashMap<>();
        Map<Object, List<String>> rulesByFileKey = new HashMap<>();
        ruleFiles.forEach((rule, ruleFile) -> {
            rulesByFileName.computeIfAbsent(ruleFile.fileName, __ -> new ArrayList<>()).add(rule);
            if (ruleFile.isRegularFile()) {
                rulesByFileKey.computeIfAbsent(ruleFile.attributes.fileKey(), __ -> new ArrayList<>()).add(rule);
            }
        });

        Set<String> result = new HashSet<>();
        Stream.concat(rulesByFileName.values().stream(), rulesByFileKey.values().stream()).forEach(candidates -> {
            for (int i = 0; i < candidates.size(); i++) {
                for (int j = i + 1; j < candidates.size(); j++) {
                    if (ruleFiles.get(candidates.get(i)).pointsToSameFileAs(ruleFiles.get(candidates.get(j)))) {
                        result.add(candidates.get(i));
                        result.add(candidates.get(j));
                    }
                }
            }
        });
        return result;
    }
